import{d as c,C as t,o as u,c as b,j as a,a as n,E as r,a3 as g}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第七十三章","description":"辨敢与不敢两种勇，依王注读圣人犹难及天道四善，连回天网疏而不失。","frontmatter":{"title":"道德经第七十三章","description":"辨敢与不敢两种勇，依王注读圣人犹难及天道四善，连回天网疏而不失。","category":"guide","aliases":["道德经第七十三章","老子第七十三章","dao de jing chapter 73"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-73.md","filePath":"daoism/dao-de-jing/chapter-73.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-73.md"},w=c({...m,setup(p){const o=[{id:"two-directions-of-courage",label:"勇于敢则杀，勇于不敢则活",showLabel:!0,sentences:[["勇于",{text:"敢",glossary:"gan"},"则杀，勇于不",{text:"敢",glossary:"gan"},"则活。"]],note:["【白话】勇于强行敢为，会招致杀身之祸；勇于有所不敢，则能保全生命。两句把勇的不同取向与不同结果并列。","【王弼注择要】敢下注「必不得其死也」，不敢下注「必齐命也」，分别从不得善终与保全其命解释。","【读法】杀在这一注释取径中说遭杀身之祸，不是把勇敢的成果译为可以杀人；不敢也有勇，是能克制强行而为的冲动。"]},{id:"different-uses-and-outcomes",label:"此两者，或利或害",showLabel:!0,sentences:[["此两者，或利或害。"]],note:["【白话】这两种勇，有的带来利益，有的带来祸害。它们都叫勇，却不能仅凭这个名称就认为施用与后果相同。","【王弼注择要】「俱勇而所施者异，利害不同，故曰或利或害也。」注把差别落在所施，而不只比较胆量大小。","【读法】此句承前而说，不可抽成凡事都勇于敢就好，也不可用不敢替代每一次具体判断；经文接着就提出谁能知其故的问题。"]},{id:"even-the-sage-is-cautious",label:"天之所恶，孰知其故",showLabel:!0,sentences:[["天之所",{text:"恶",glossary:"wu"},"，孰知其故？是以圣人犹",{text:"难",glossary:"nan-treat"},"之。"]],note:["【白话】天所厌恶的，谁能知道它的缘故？因此，即使圣人也仍把这件事看得艰难，慎重对待，不轻率自定。","【王弼注择要】「夫圣人之明，犹难于勇敢」，下文又以「故曰犹难之也」收束，强调即使明者仍不轻率行勇敢。","【读法】恶读 wù，难作以为有难处、慎重对待。所据注另出现天下之所恶等连文，本页不擅删下字后冒作逐字引文。"]},{id:"winning-without-contending",label:"天之道，不争而善胜",showLabel:!0,sentences:[["天之道，",{text:"不争",glossary:"buzheng"},"而善胜，"]],note:["【白话】天的运行之道，不与物争夺，却善于成就其胜。经文从人的敢与不敢，转向以天道说明另一种成用方式。","【王弼注择要】「天虽不争，故天下莫能与之争。」注以不争本身说明无可与争，不补作天与万物争抢地位。","【读法】这里保留古代以天道论人事的表达。与第六十六章不争参读，要连同处下与承接理解，不抽作个人竞赛的取胜保证。"]},{id:"responding-without-speaking",label:"不言而善应",showLabel:!0,sentences:[["不言而善",{text:"应",glossary:"ying"},"，"]],note:["【白话】天不发言，却善于回应。虽然没有口头命令，运行中的顺逆与吉凶仍显出相应关系，这是经文以人事语言写天道。","【王弼注择要】「顺则吉，逆则凶，不言而善应也。」注把应解释为顺逆各有所应。","【读法】应读 yìng。吉凶的古代判断要如实保留，但不能直接拿一时遭际反推某个人必然顺天或逆天。"]},{id:"arrival-without-summoning",label:"不召而自来",showLabel:!0,sentences:[["不",{text:"召",glossary:"zhao"},"而自来，"]],note:["【白话】不出声召唤，事物却自行来到。依王注，这种归来与处下有关，不靠主动招徕、驱迫才形成归附。","【王弼注择要】「处下则物自归。」注把不召而来的成用，与江海处下、众流归入的阅读线索相接。","【读法】可连第六十一章下流、第六十六章百谷王参读。不召仍有处下的条件，不等于任何事情不作准备就会自动到来。"]},{id:"unhurried-and-prepared",label:"繟然而善谋",showLabel:!0,sentences:[[{text:"繟然",glossary:"chanran"},"而善谋。"]],note:["【白话】宽舒坦然，却善于谋虑。外在不显迫促，与事先留意变化、安时不忘危可以并存。","【王弼注择要】「安而不忘危，未召而谋之」，注由此解释繟然而善谋。","【读法】繟然读 chǎn rán，取宽舒、坦然。所据前注另作先事而设诚，本页不猜改诚字后作引文；这里择引可明确对应的安不忘危与预先谋虑。"]},{id:"the-vast-net",label:"天网恢恢，疏而不失",showLabel:!0,sentences:[["天网",{text:"恢恢",glossary:"huihui"},"，",{text:"疏",glossary:"shu"},"而不失。"]],note:["【白话】天的网广大无边，网眼虽疏，却没有遗漏。末句用网的形象，收束天道不争而能胜、不言而善应的意思。","【读法】恢恢为广大，疏是网眼疏阔，不是使人疏远；所据末句未见单独逐句王注。","【读法】这个古代天道取象常被引申为行为终有其应。现代借用时仍要查明事实、承担处置，不能据一句天网就断言现实中所有不公都会自行、即时解决。"]}],s=[{id:"gan",term:"敢",sense:1},{id:"wu",term:"恶",sense:1},{id:"nan-treat",term:"难",sense:2},{id:"buzheng",term:"不争",sense:1},{id:"ying",term:"应",sense:1},{id:"zhao",term:"召",sense:1},{id:"chanran",term:"繟然",sense:1},{id:"huihui",term:"恢恢",sense:1},{id:"shu",term:"疏",sense:2}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第七十三章",tabindex:"-1"},[n("道德经第七十三章 "),a("a",{class:"header-anchor",href:"#道德经第七十三章","aria-label":'Permalink to "道德经第七十三章"'},"​")],-1)),r(i,{title:"勇于不敢，为什么仍然是一种勇",summary:"本章先比较敢与不敢两种勇，指出它们的施用与利害不同。随后说即使圣人也慎重看待天之所恶，再以不争、不言、不召、繟然写天道的成用。结尾天网之喻，须连着前面的善应与慎重来读。",points:[{label:"先读",text:"敢与不敢都被称作勇；不要先把不敢等同胆怯，再错过两种施用的差别。"},{label:"再辨",text:"天之所恶之后有孰知其故与圣人犹难之，保留这层不轻断的态度。"},{label:"后看",text:"天道四句都以少强作而能成用为线索，繟然还连着王注安不忘危。"}],hint:"恶读 wù，难之读 nán zhī，应读 yìng，繟然读 chǎn rán。杀依王注在本句取遭杀身之祸，不直接作杀别人解。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[n("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:o,glossary:s}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[n("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"勇于敢则杀，勇于不敢则活。",tone:"先辨勇的施用",guide:"依王注不得其死、齐命读，不以敢的外观替代结果判断。"},{text:"天之所恶，孰知其故？是以圣人犹难之。",tone:"不轻断的转折",guide:"在讨论天道成用之前，先保留圣人仍慎重对待的态度。"},{text:"天之道，不争而善胜，不言而善应，不召而自来，繟然而善谋。",tone:"少强作仍能成用",guide:"四句分别落在胜、应、来、谋，繟然并不取消安不忘危。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[n("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:s}),e[4]||(e[4]=g("",15))])}}});export{_ as __pageData,w as default};
